/**
 * THE BUILD STAMP (versioning wave, owner 2026-11): "is the running app
 * actually the build I just shipped" — build-info.json is REGENERATED by
 * scripts/write-build-info.mjs on every `npm run build` / `npm run dev`
 * (prebuild/predev hooks, package.json) and committed with a stub
 * fallback so a fresh clone never breaks the import before the first
 * build (same regenerated-but-committed idiom as the Next.js AGENTS.md
 * header). Static import — baked into the bundle at build time, no
 * runtime fs read, works the same in the standalone server and Electron.
 */
import data from "./build-info.json";

export interface BuildInfo {
	/** package.json version — human intent, bumped by hand. */
	version: string;
	/** `git rev-parse --short HEAD`, "-dirty" suffixed when the tree had
	 *  uncommitted changes at build time; "unknown" outside a git checkout. */
	commit: string;
	/** ISO timestamp of the build/dev-server start that last wrote this file. */
	builtAt: string;
}

export const buildInfo: BuildInfo = data as BuildInfo;
